import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static final long MOD = 998244353;
    static long[] h;
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        int[] ns = new int[t];
        long[][] a = new long[t][];
        int mx=0;
        for(int tc=0;tc<t;tc++)
        {
            int n = sc.nextInt();
            ns[tc] = n;
            mx = Math.max(mx,n);
            a[tc] = new long[n];
            for(int i=0;i<n;i++){
                a[tc][i] = sc.nextLong();
            }
        }
        h = new long[mx+1];
        long inv =1;
        for(int i=1;i<=mx;i++){
            inv = modPow(i,MOD-2);
            h[i] = (h[i-1]+inv)%MOD;
        }
        for(int tc = 0;tc<t;tc++)
        {
            int n = ns[tc];
            long ans =0;
            for(int i=0;i<n;i++)
            {
                long coef = (h[i]+h[n-i-1])%MOD;
                ans = (ans+a[tc][i]%MOD*coef)%MOD;
            }
            System.out.println(ans);
        }
	}
	static long modPow(long a,long b){
	    long r=1;
	    while(b>0){
	        if((b&1) ==1) r= r*a%MOD;
	        a = a*a%MOD;
	        b>>=1;
	    }
	    return r;
	}
}
